// =============================================================================
// Plik: protocol/requests.js
// Opis: Request bodies of the binary protocol, as CBOR bytes. Every function
//       turns its arguments into the JSON fields of one wire variant (snake_case,
//       exactly the Rust field names) and hands them to the wasm schema encoder
//       `encodeBody(path, variant, json)`; the wasm validates names, required
//       fields and scalar ranges against the protocol types. `path` is the chain
//       of wrapper variants (`ProjectStudioBody.Access`), outermost first, empty
//       for a top-level MessageBody variant.
//       A byte field is passed as `{ $bytes: n }` and the n-th Uint8Array of the
//       call, so a file never becomes a JSON array of numbers.
// Przyklad:
//   import { requests } from './requests.js';
//   const body = requests.encodeAddonOAuthConfigListRequest('my-addon');
// =============================================================================

import * as wasm from './wasm_glue.js';

const BIGINT_MARK = '\u0001bigint:';
const BIGINT_LITERAL = new RegExp(`"\\\\u0001bigint:(-?\\d+)"`, 'g');

/** JSON text of `value`; a BigInt becomes an exact integer literal (u64 above 2^53 survives). */
function toJson(value) {
  return JSON.stringify(value, (_key, item) => (typeof item === 'bigint' ? `${BIGINT_MARK}${item}` : item))
    .replace(BIGINT_LITERAL, '$1');
}

function parseJson(text, what) {
  try {
    return JSON.parse(text);
  } catch (error) {
    throw new Error(`invalid ${what} json: ${error.message}`);
  }
}

const encode = (path, variant, fields) => wasm.encodeBody(path, variant, toJson(fields));
const encodeJson = (path, variant, fieldsJson) => wasm.encodeBody(path, variant, fieldsJson);
const encodeBlobs = (path, variant, fields, blobs) => wasm.encodeBodyWithBytes(path, variant, toJson(fields), blobs);

/** BusBody wraps its payload enum in a `{ instance_id, payload }` struct. */
const bus = (instanceId, variant, fields) => encode('', 'BusBody', { instance_id: instanceId, payload: { [variant]: fields } });

/** An empty string / zero from a form means "not set" for these optional fields. */
const blankToNull = (value) => (value === '' ? null : value);
const zeroToNull = (value) => (value === 0 || value === 0n ? null : value);

/** `a, b,,c` → ['a', 'b', 'c']. */
const csvList = (text) => text.split(',').map((item) => item.trim()).filter((item) => item !== '');

/** Pairs travel as `[key, value]` arrays; a missing list is empty. */
const pairs = (list) => (list == null ? [] : list);

const SYNC_RESOLUTIONS = { keep_local: 'KeepLocal', ignore: 'Ignore', accept_remote: 'AcceptRemote' };

/** The scope object of a profiling session in the wire's own enum form. */
function profileScope(scope) {
  const gpu = scope.gpuTargets;
  let gpuTargets;
  if (typeof gpu === 'string') {
    gpuTargets = { none: 'None', all: 'All' }[gpu.toLowerCase()];
    if (gpuTargets === undefined) throw new Error(`gpuTargets: unknown value '${gpu}' (expected none|all or an object)`);
  } else if (gpu?.indices != null) {
    gpuTargets = { Indices: gpu.indices };
  } else if (gpu?.byVendor != null) {
    const vendor = String(gpu.byVendor).toLowerCase();
    if (!['nvidia', 'amd', 'intel', 'apple'].includes(vendor)) throw new Error(`gpuTargets.byVendor: unknown vendor '${vendor}'`);
    gpuTargets = { ByVendor: vendor[0].toUpperCase() + vendor.slice(1) };
  } else {
    throw new Error("gpuTargets: expected 'none'|'all', {indices} or {byVendor}");
  }
  const target = scope.target;
  let wireTarget;
  if (typeof target === 'string') {
    wireTarget = { system_wide: 'SystemWide', SystemWide: 'SystemWide', own_process: 'OwnProcess', OwnProcess: 'OwnProcess' }[target];
    if (wireTarget === undefined) throw new Error(`target: unknown value '${target}' (expected system_wide|own_process or {pid})`);
  } else if (target?.pid != null) {
    wireTarget = { Pid: target.pid };
  } else {
    throw new Error("target: expected a string or {pid}");
  }
  return {
    sources: scope.sources,
    gpu_targets: gpuTargets,
    cpu_sampling_hz: scope.cpuSamplingHz,
    target: wireTarget,
    duration_seconds: scope.durationSeconds,
    label: scope.label,
  };
}

