  encodeBusOffsetResetRequest: (instanceId, group, topic, partition, mode, offset, tsMs) => {
    let wireMode;
    if (mode === 'earliest') wireMode = 'Earliest';
    else if (mode === 'latest') wireMode = 'Latest';
    else if (mode === 'explicit') {
      if (offset == null) throw new Error('explicit mode requires an offset');
      wireMode = { Explicit: { offset } };
    } else if (mode === 'timestamp') {
      if (tsMs == null) throw new Error('timestamp mode requires ts_ms');
      wireMode = { Timestamp: { ts_ms: tsMs } };
    } else throw new Error(`unknown offset reset mode '${mode}'`);
    return bus(instanceId, 'OffsetResetRequest', { group, topic, partition, mode: wireMode });
  },
